import subprocess, re, itertools, string

def suggests(cmd):
    p=subprocess.run(["./executable",cmd], capture_output=True, text=True)
    out=p.stdout
    if 'did you mean' in out:
        m=re.search(r'did you mean "(.*?)"', out)
        return m.group(1) if m else "?"
    else:
        return None

