}

type goListError struct {
	ImportStack []string `json:"ImportStack"`
	Pos         string   `json:"Pos"`
	Err         string   `json:"Err"`
}

func loadPackages(patterns []string) ([]*goListPackage, error) {
	if len(patterns) == 0 {
		return nil, nil
	}
	// Check for mixing files and packages: if any ends with .go and any doesn't, return mixing error
	hasGoFile := false
	hasNonGoFile := false
	var firstNonGo string
	for _, p := range patterns {
		if strings.HasSuffix(p, ".go") {
			hasGoFile = true
		} else {
			hasNonGoFile = true
			if firstNonGo == "" {
				firstNonGo = p
			}
		}
	}
	if hasGoFile && hasNonGoFile {
		return nil, fmt.Errorf("-: named files must be .go files: %s", firstNonGo)
	}
	cmd := exec.Command("go", append([]string{"list", "-e", "-json"}, patterns...)...)
	// Use current dir and env
	var stdout bytes.Buffer
	var stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	// Run; ignore exit code? go list exits 0 even with errors (due to -e)
	_ = cmd.Run()
	out := stdout.Bytes()
	// If output is empty, check stderr? For cases like "go: go.mod file not found", stdout empty, stderr has message.
	// In that case, return no packages, no error (silent).
	if len(bytes.TrimSpace(out)) == 0 {
		return nil, nil
	}
	// Output may contain multiple JSON objects concatenated. Decode stream.
	var pkgs []*goListPackage
	dec := json.NewDecoder(bytes.NewReader(out))
	for dec.More() {
		var pkg goListPackage
		if err := dec.Decode(&pkg); err != nil {
			// If decode fails (e.g., output contains non-JSON like "stat ..."), return no packages silent?
			// For file not found case, output is "stat ..." (not JSON), so fail silent.
