package main

import (
	"fmt"
	"go/token"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
)

type Warning struct {
	Filename string
	Line     int
	Col      int
	Checker  string
	Text     string
}

func (w Warning) String(shorter bool) string {
	display := w.Filename
	if shorter {
		display = shortenPath(w.Filename)
	}
	return fmt.Sprintf("%s:%d:%d: %s: %s", display, w.Line, w.Col, w.Checker, w.Text)
}

func shortenPath(path string) string {
	// Try relative to cwd first
	cwd, err := os.Getwd()
	if err == nil {
		if rel, err := filepath.Rel(cwd, path); err == nil && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != ".." {
			// Use "./"+rel as in original
			// For files in cwd, rel is "main.go", display "./main.go"
			// For files in sub, rel is "sub/file.go", display "./sub/file.go"
			// What about when path == cwd? Not a file, ignore.
			return "./" + filepath.ToSlash(rel)
		}
	}
	// Try GOROOT
	goroot := runtime.GOROOT()
