package main

import (
	"go/ast"
	"go/token"
	"sync"
)

func runCheckers(pkgs []*goListPackage, enabled map[string]bool, flags *checkFlags) []Warning {
	var allWarnings []Warning
	var mu sync.Mutex
	// Use worker pool limited by concurrency? For simplicity, use goroutines per package/file with semaphore.
	// Since sorting makes order deterministic, concurrency doesn't affect output.
	// We'll just run sequentially for now, but respect concurrency via semaphore to avoid hanging? Already handled 0/negative.
	// For positive concurrency, run with limited parallelism.
	sem := make(chan struct{}, flags.concurrency)
	var wg sync.WaitGroup
	for _, pkg := range pkgs {
		// Get files for this package
		files := getPackageFiles(pkg, flags.checkTests)
		if len(files) == 0 {
			continue
		}
		// Parse and type-check this package
		fset := token.NewFileSet()
		parsedFiles, pkgTypes, info, filenames := parseAndCheck(files, fset)
		if len(parsedFiles) == 0 {
			continue
		}
		// For each file, run checkers
		for idx, file := range parsedFiles {
			fname := filenames[idx]
			_ = fname
			// Check generated
			if !flags.checkGenerated && isGeneratedFile(file) {
				continue
			}
			// Need fileContext
			ctx := &fileContext{
				fset:     fset,
				file:     file,
				filename: fname,
				pkg:      pkgTypes,
				info:     info,
				params:   flags,
			}
			// Run checkers for this file (with concurrency control)
			// To match original's per-file concurrency? We'll just run sequentially inside goroutine per file.
			sem <- struct{}{}
			wg.Add(1)
			go func(c *fileContext) {
				defer wg.Done()
				defer func() { <-sem }()
				var fileWarnings []Warning
				for name := range enabled {
					fn, ok := checkerFuncs[name]
					if !ok || fn == nil {
						continue
					}
					ws := fn(c)
					fileWarnings = append(fileWarnings, ws...)
				}
				mu.Lock()
				allWarnings = append(allWarnings, fileWarnings...)
				mu.Unlock()
			}(ctx)
		}
	}
	wg.Wait()
	// Handle duplicate files? Our parseAndCheck deduplicates? No, it keeps duplicates as separate entries in parsedFiles?
	// For duplicate file args (same file twice), files = ["/tmp/a.go", "/tmp/a.go"], parseAndCheck will parse same file twice (two ASTs with same filename but different FileSet entries).
	// That's correct for duplicate warnings.
	// However, what about files that failed to parse? They are skipped, but checking line still counts them (as per go list). That's correct (checking shows total from go list, not parsed).
	_ = ast.Node(nil)
	return allWarnings
}
