		typeStr := getTypeString(typ, typeExpr, ctx)
		// For pointer, need parens? Original shows "(*int)(nil)" (with parens). For slice "[]int(nil)" (no parens), map "map[string]int(nil)", interface "interface{}(nil)".
		// When to add parens? For pointer, yes. For others, no.
		if _, isPtr := t.(*types.Pointer); isPtr {
