			return fmt.Sprintf("(%s)(nil)", typeStr)
		}
		return fmt.Sprintf("%s(nil)", typeStr)
	case *types.Struct, *types.Array:
		typeStr := getTypeString(typ, typeExpr, ctx)
		return fmt.Sprintf("%s{}", typeStr)
	case *types.Chan, *types.Signature:
		return ""
	default:
