		// If typ is named (defined), use underlying? Actually typ.Underlying() already gives underlying, but we switched on underlying.
		// For named struct, underlying is struct, so we go to struct case, typeStr should be "MyStruct"? Or underlying struct string?
		// Original likely uses typeExpr text (as in source) for suggestion? For *new(MyStruct), suggestion "MyStruct{}"? Let's use typeExpr text.
		// For now, fallback to typeExpr printer + "{}" or "(nil)" etc based on underlying?
		// Since we already handled underlying struct/array etc, this default is for other named? Actually named types' underlying is already handled above, so this default won't be reached for named? Wait: typ.Underlying() for named MyInt (underlying int) is Basic int, so it goes to Basic case. Good.
		// For named struct, underlying struct, goes to struct case. Good.
		// So default is for unexpected (e.g., TypeParam, Union, etc). Return "" to skip.
		_ = t
		return ""
	}
}

func getTypeString(typ types.Type, typeExpr ast.Expr, ctx *fileContext) string {
	// Use printer for typeExpr to get normalized string (as original does for struct etc).
	// For basic types like int8, typeExpr is ident "int8", printer gives "int8". Good.
	// For *int, typeExpr is StarExpr, printer gives "*int". Good. But for suggestion we need "(*int)" with parens, handled above.
	// For []int, printer gives "[]int". Good.
	var buf bytes.Buffer
	_ = printer.Fprint(&buf, ctx.fset, typeExpr)
	return buf.String()
}

func isFloatKind(k types.BasicKind) bool {
	return k == types.Float32 || k == types.Float64 || k == types.UntypedFloat
}

func isComplexKind(k types.BasicKind) bool {
	return k == types.Complex64 || k == types.Complex128 || k == types.UntypedComplex
}
