					return true
				}
				return true
			})
			// Walk body, skipping FuncLit subtrees
			var walk func(n ast.Node)
			walk = func(n ast.Node) {
				if n == nil {
					return
				}
				// If FuncLit, skip its body (don't descend)
				if _, ok := n.(*ast.FuncLit); ok {
					return
