			}
			// Use Inspect with FuncLit skipping
			ast.Inspect(fn.Body, func(nn ast.Node) bool {
				if _, ok := nn.(*ast.FuncLit); ok {
					return false // don't descend into FuncLit
				}
				if vs, ok := nn.(*ast.ValueSpec); ok {
					for _, name := range vs.Names {
						if isCapitalized(name.Name) {
							warnings = append(warnings, makeWarning(ctx.fset, name.Pos(), "captLocal", "`"+name.Name+"' should not be capitalized"))
						}
					}
				}
				if as, ok := nn.(*ast.AssignStmt); ok {
					if as.Tok == token.DEFINE && !typeSwitchAssigns[as] {
						for _, lhs := range as.Lhs {
							if ident, ok := lhs.(*ast.Ident); ok {
								if isCapitalized(ident.Name) {
									warnings = append(warnings, makeWarning(ctx.fset, ident.Pos(), "captLocal", "`"+ident.Name+"' should not be capitalized"))
								}
							}
						}
					}
				}
				return true
			})
			_ = walk
		}
		return true
	})
	return warnings
}

func isCapitalized(name string) bool {
	if name == "" || name == "_" {
		return false
	}
	r := rune(name[0])
	// Handle underscore prefix? "_IN" starts with _, not upper, so false. Good.
	return unicode.IsUpper(r)
}
