package main

import (
	"go/ast"
	"strings"
)

func checkCommentFormatting(ctx *fileContext) []Warning {
	var warnings []Warning
	for _, cg := range ctx.file.Comments {
		for _, c := range cg.List {
			text := c.Text
			// Only line comments starting with //
			if !strings.HasPrefix(text, "//") {
				continue
			}
			// Exclude block-style? Already only //.
			rest := text[2:]
			if rest == "" {
				continue
			}
			// If starts with space or tab, OK
			if rest[0] == ' ' || rest[0] == '\t' {
				continue
			}
			// Exclude ///... (starting with /)
			if rest[0] == '/' {
				continue
			}
			// Exclude go: directives? Check if rest starts with "go:"? Actually text is "//go:..." -> rest is "go:..."
			if strings.HasPrefix(rest, "go:") {
				continue
			}
			// Exclude +, -, !, # at start?
			if rest[0] == '+' || rest[0] == '-' || rest[0] == '!' || rest[0] == '#' {
				continue
			}
			// Exclude single-char? If len(rest)==1, skip? As observed, //a (single) doesn't trigger.
			if len(rest) == 1 {
				continue
			}
			warnings = append(warnings, makeWarning(ctx.fset, c.Pos(), "commentFormatting", "put a space between `//` and comment text"))
		}
	}
	_ = ast.Node(nil)
	return warnings
}
