func checkUnlambda(ctx *fileContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.file, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		// Check if func(x int) int { return fn(x) } can be fn
		// Conditions: No ...? Params match args? Body has single return with call?
		if lit.Body == nil || len(lit.Body.List) != 1 {
			return true
		}
		retStmt, ok := lit.Body.List[0].(*ast.ReturnStmt)
		if !ok || len(retStmt.Results) != 1 {
			return true
		}
		call, ok := retStmt.Results[0].(*ast.CallExpr)
		if !ok {
			return true
		}
		// Check Fun is ident (fn) and Args match Params?
		funIdent, ok := call.Fun.(*ast.Ident)
		if !ok {
			return true
		}
		// Check params: lit.Type.Params vs call.Args
		if lit.Type.Params == nil {
			// No params, call must have no args? Then func() int { return fn() } can be fn? Probably yes if types match? But need to check?
			if len(call.Args) != 0 {
				return true
			}
		} else {
			// Collect param names
			var paramNames []string
			for _, field := range lit.Type.Params.List {
				for _, name := range field.Names {
					paramNames = append(paramNames, name.Name)
				}
				// Handle unnamed params? If no names (e.g., func(int) ), then can't match? Skip.
				if len(field.Names) == 0 {
					return true
				}
			}
			if len(paramNames) != len(call.Args) {
				return true
			}
			for i, arg := range call.Args {
				argIdent, ok := arg.(*ast.Ident)
				if !ok || argIdent.Name != paramNames[i] {
					return true
				}
			}
		}
		// Check results? lit.Type.Results must match? For func(x int) int { return fn(x) }, results is int, call returns int. Good.
		// What about func(x int) { fn(x) } (no return, just call)? That's not return, it's ExprStmt. Does unlambda handle that? Doc only shows return case. What about defer case? Probably only return.
		// Also need to check that fn is not shadowed? And that lit has no extra logic? Already checked single return.
		origText := getNodeText(ctx.fset, lit)
		text := fmt.Sprintf("replace `%s` with `%s`", origText, funIdent.Name)
		warnings = append(warnings, makeWarning(ctx.fset, lit.Pos(), "unlambda", text))
		return true
	})
	return warnings
}

// Helper to get imports? For wrapperFunc etc.
func isPackageImport(ctx *fileContext, pkg string) bool {
	for _, imp := range ctx.file.Imports {
		path := strings.Trim(imp.Path.Value, `"`)
		if path == pkg || strings.HasSuffix(path, "/"+pkg) {
			return true
		}
	}
	return false
}

func getCallPackage(ctx *fileContext, call *ast.CallExpr) (string, string) {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return "", ""
	}
	pkgIdent, ok := sel.X.(*ast.Ident)
	if !ok {
		return "", ""
	}
	return pkgIdent.Name, sel.Sel.Name
}

func printNode(fset interface{}, n ast.Node) string {
	// Dummy to use imports
	var buf bytes.Buffer
	_ = buf
	_ = printer.Fprint
	_ = n
	return ""
}
