		// Check for xs[len(xs)] (should be len-1)
		// X is xs, Index is len(xs) where xs same as X?
		lenCall, ok := idx.Index.(*ast.CallExpr)
		if !ok || !isLenCall(lenCall) {
			return true
		}
		if len(lenCall.Args) != 1 {
			return true
		}
		if !exprEqual(idx.X, lenCall.Args[0]) {
			return true
		}
		// Warn
		xsText := getNodeText(ctx.fset, idx.X)
		text := fmt.Sprintf("index expr always panics; maybe you wanted %s[len(%s)-1]?", xsText, xsText)
		warnings = append(warnings, makeWarning(ctx.fset, idx.Pos(), "offBy1", text))
		return true
	})
	return warnings
}
