			xText := getNodeText(ctx.fset, s1.Rhs[0])
			suggest := fmt.Sprintf("%s, %s = %s, %s", yText, wText, zText, xText)
			text := fmt.Sprintf("can re-write as `%s`", suggest)
			warnings = append(warnings, makeWarning(ctx.fset, s1.Pos(), "valSwap", text))
		}
		return true
	})
