func checkExitAfterDefer(ctx *fileContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.file, func(n ast.Node) bool {
		fn, ok := n.(*ast.FuncDecl)
		if !ok {
			return true
		}
		if fn.Body == nil {
			return true
		}
		// Find defers in function
		var defers []*ast.DeferStmt
		ast.Inspect(fn.Body, func(nn ast.Node) bool {
			if d, ok := nn.(*ast.DeferStmt); ok {
				defers = append(defers, d)
			}
			// Don't descend into FuncLit? Defer inside FuncLit is for inner func, not outer. So skip FuncLit.
			if _, ok := nn.(*ast.FuncLit); ok {
				return false
			}
			return true
		})
		if len(defers) == 0 {
			return true
		}
		// Find calls to os.Exit, log.Fatal, log.Fatalf, log.Fatalln?
		ast.Inspect(fn.Body, func(nn ast.Node) bool {
			if _, ok := nn.(*ast.FuncLit); ok {
				return false
			}
			call, ok := nn.(*ast.CallExpr)
			if !ok {
				return true
			}
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			pkgIdent, ok := sel.X.(*ast.Ident)
			if !ok {
				return true
			}
			isExit := false
			callText := ""
			if pkgIdent.Name == "os" && sel.Sel.Name == "Exit" {
				isExit = true
				callText = "os.Exit"
			} else if pkgIdent.Name == "log" && (sel.Sel.Name == "Fatal" || sel.Sel.Name == "Fatalf" || sel.Sel.Name == "Fatalln") {
				isExit = true
				callText = "log." + sel.Sel.Name
			}
			if isExit {
				// Use first defer for message? Original: "log.Fatalf will exit, and `defer os.Remove(\"f\")` will not run"
				deferText := getNodeText(ctx.fset, defers[0])
				text := fmt.Sprintf("%s will exit, and `%s` will not run", callText, deferText)
				warnings = append(warnings, makeWarning(ctx.fset, call.Pos(), "exitAfterDefer", text))
			}
			return true
		})
		return true
	})
	// Also need to handle FuncLit? For "func() { defer ...; os.Exit() }"? Probably also. But our outer only checks FuncDecl. Should also check FuncLit? Let's also check FuncLit bodies.
	ast.Inspect(ctx.file, func(n ast.Node) bool {
		lit, ok := n.(*ast.FuncLit)
		if !ok {
			return true
		}
		if lit.Body == nil {
			return true
		}
		var defers []*ast.DeferStmt
		ast.Inspect(lit.Body, func(nn ast.Node) bool {
			if d, ok := nn.(*ast.DeferStmt); ok {
				defers = append(defers, d)
			}
			if _, ok := nn.(*ast.FuncLit); ok && nn != lit {
				return false
			}
			return true
		})
		if len(defers) == 0 {
			return true
		}
		ast.Inspect(lit.Body, func(nn ast.Node) bool {
			if innerLit, ok := nn.(*ast.FuncLit); ok && innerLit != lit {
				return false
			}
			call, ok := nn.(*ast.CallExpr)
			if !ok {
				return true
			}
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			pkgIdent, ok := sel.X.(*ast.Ident)
			if !ok {
				return true
			}
			isExit := false
			callText := ""
			if pkgIdent.Name == "os" && sel.Sel.Name == "Exit" {
				isExit = true
				callText = "os.Exit"
			} else if pkgIdent.Name == "log" && (sel.Sel.Name == "Fatal" || sel.Sel.Name == "Fatalf" || sel.Sel.Name == "Fatalln") {
				isExit = true
				callText = "log." + sel.Sel.Name
			}
			if isExit {
				deferText := getNodeText(ctx.fset, defers[0])
				text := fmt.Sprintf("%s will exit, and `%s` will not run", callText, deferText)
				warnings = append(warnings, makeWarning(ctx.fset, call.Pos(), "exitAfterDefer", text))
			}
			return true
		})
		return true
	})
	return warnings
}

func checkValSwap(ctx *fileContext) []Warning {
	var warnings []Warning
	ast.Inspect(ctx.file, func(n ast.Node) bool {
		block, ok := n.(*ast.BlockStmt)
		if !ok {
			return true
		}
		// Look for 3 consecutive assignments forming swap without parallel assignment?
		// Original example: "*tmp = *x; *x = *y; *y = *tmp" -> "*x, *y = *y, *x"
		// Our earlier test: "tmp := *x; *x = *y; *y = tmp" -> "can re-write as `*x, *y = *y, *x`"
		// So pattern: tmp := A; B = C; D = tmp (where tmp is temp var)? Or tmp = A; B=C; D=tmp?
		// Let's implement simple: Look for tmp := X; Y = Z; W = tmp where tmp is ident defined in first, used in last, and X,Y,Z,W are *p etc?
		// For now, handle: tmp := *x; *x = *y; *y = tmp (with tmp being ident, X=*x, Y=*x, Z=*y, W=*y, tmp in last RHS)
		stmts := block.List
		for i := 0; i+2 < len(stmts); i++ {
			s1, ok1 := stmts[i].(*ast.AssignStmt)
			s2, ok2 := stmts[i+1].(*ast.AssignStmt)
			s3, ok3 := stmts[i+2].(*ast.AssignStmt)
			if !ok1 || !ok2 || !ok3 {
				continue
			}
			// s1 must be tmp := ... (define, single LHS ident, single RHS)
			if s1.Tok != token.DEFINE || len(s1.Lhs) != 1 || len(s1.Rhs) != 1 {
				continue
			}
			tmpIdent, ok := s1.Lhs[0].(*ast.Ident)
			if !ok {
				continue
			}
			tmpName := tmpIdent.Name
			// s2 must be Y = Z (assign, single)
			if s2.Tok != token.ASSIGN || len(s2.Lhs) != 1 || len(s2.Rhs) != 1 {
				continue
			}
			// s3 must be W = tmp (assign, RHS is tmp ident)
			if s3.Tok != token.ASSIGN || len(s3.Lhs) != 1 || len(s3.Rhs) != 1 {
				continue
			}
			rhs3Ident, ok := s3.Rhs[0].(*ast.Ident)
			if !ok || rhs3Ident.Name != tmpName {
				continue
			}
			// Check that s1.Rhs (X) == s2.Lhs (Y)? And s2.Rhs (Z) == s3.Lhs (W)? For swap: tmp:=*x; *x=*y; *y=tmp => X=*x, Y=*x (equal), Z=*y, W=*y (equal). Good.
			if !exprEqual(s1.Rhs[0], s2.Lhs[0]) {
				continue
			}
			if !exprEqual(s2.Rhs[0], s3.Lhs[0]) {
				continue
			}
			// Found swap, suggest parallel assignment: Y, W = Z, X? Actually *x, *y = *y, *x (Y,W = Z,X)
			yText := getNodeText(ctx.fset, s2.Lhs[0])
			wText := getNodeText(ctx.fset, s3.Lhs[0])
			zText := getNodeText(ctx.fset, s2.Rhs[0])
			xText := getNodeText(ctx.fset, s1.Rhs[0])
			suggest := fmt.Sprintf("%s, %s = %s, %s", yText, wText, zText, xText)
			text := fmt.Sprintf("can re-write as `%s`", suggest)
			warnings = append(warnings, makeWarning(ctx.fset, s1.Pos(), "valSwap", text))
		}
		return true
	})
	_ = strings.Contains
	return warnings
}
