	}
	// Find enclosing func
	var enclosing *ast.FuncDecl
	ast.Inspect(ctx.file, func(nn ast.Node) bool {
		if fn, ok := nn.(*ast.FuncDecl); ok && fn.Body != nil {
			if n.Pos() >= fn.Body.Lbrace && n.Pos() <= fn.Body.Rbrace {
				enclosing = fn
			}
		}
		return true
	})
	if enclosing == nil {
		return false
	}
	name := enclosing.Name.Name
	if len(name) >= 4 && (name[:4] == "Test" || name[:4] == "Fuzz") {
